import{_ as t}from"./chunks/portal-home.iKqvMfFH.js";import{_ as o,o as a,c as s,a3 as i}from"./chunks/framework.DhF4LrUq.js";const r="/shipperdog/snapshot/screenshots/portal-login.png",n="/shipperdog/snapshot/screenshots/roles/portal-version-install.png",m=JSON.parse('{"title":"Tester quickstart","description":"The Tester quickstart — accept your invitation, sign in to the Tester Portal, find your first app, and install your first build. Phone only, five minutes.","frontmatter":{"description":"The Tester quickstart — accept your invitation, sign in to the Tester Portal, find your first app, and install your first build. Phone only, five minutes."},"headers":[],"relativePath":"roles/tester.md","filePath":"roles/tester.md"}'),l={name:"roles/tester.md"};function h(p,e,u,d,c,g){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="tester-quickstart" tabindex="-1">Tester quickstart <a class="header-anchor" href="#tester-quickstart" aria-label="Permalink to &quot;Tester quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You test mobile apps — the newest builds, before anybody else sees them. Someone on the product team invited you by email; from that invite to a running build on your phone takes under five minutes. Your system role is <strong><code>TENANT_TESTER</code></strong>, and your entire experience is the <strong>Tester Portal</strong>, a website you open on your phone (plus, if your team uses it, a small companion installer app). There is nothing to install up front, no account to create anywhere else, and nobody to ask for help: the invitation email is the whole onboarding. This guide is the standalone track — if you also work on the product team itself, use the <a href="/shipperdog/snapshot/roles/">other role guides</a> separately.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p>Three things, and they are the whole job:</p><ul><li><strong>See the applications you are authorized to test</strong> — one card per app, with its latest available build.</li><li><strong>Install those builds</strong> — download for your platform (Android or iOS) with install guidance that knows what kind of build it is.</li><li><strong>Report issues</strong> — bug, crash, or wish, with your device, OS, and the exact build attached automatically.</li></ul><p>What you cannot do is equally deliberate: you cannot see apps nobody granted you, and you cannot see other testers&#39; information. Your access is exactly what your team configured — an honest empty list means they have not granted you anything yet, and it is never an error.</p><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>Realistically this takes five. The screenshots come from a phone-sized browser against a live portal — what you see here is what you will see on your phone.</p><ol><li><p><strong>Open your invitation email on your phone.</strong> The link takes you to the portal&#39;s invitation page. Set a password — that is the entire registration. The link is single-use and expires after seven days; if it has gone stale, ask your team for a fresh one.</p><p><img src="'+r+'" alt="The Tester Portal sign-in"></p></li><li><p><strong>Sign in.</strong> Use the email address the invitation was sent to and the password you just set. The portal address is whatever your team gave you — bookmark it, you will come back every time a new build lands.</p></li><li><p><strong>Find your first app.</strong> The home screen is <strong>My Applications</strong>: one card per application you are authorized to install, each with its latest available version and which platforms have builds ready. Tap the card.</p><p><img src="'+t+'" alt="My Applications on the Tester Portal"></p></li><li><p><strong>Pick a build.</strong> The version history lists builds newest first, each with its status badge, build number, size, and upload date. When you report an issue, you report it against exactly one of these — the link to a single version is shareable, which keeps &quot;which build were you on?&quot; out of everyone&#39;s life.</p></li><li><p><strong>Install it.</strong> Tap <strong>Download</strong> for your platform. The portal checks whether you may have this build, then hands you a short-lived download together with install guidance:</p><ul><li><strong>Android</strong> — allow installs from this source if your phone asks once, then the build installs.</li><li><strong>iOS</strong> — for ad-hoc or enterprise-signed builds your registered device installs directly; most iOS testing flows through TestFlight instead, and the guidance says so when that is the route.</li></ul><p><img src="'+n+'" alt="The version page with download and report"></p><p>If the download offers a <strong>telemetry token</strong>, the build embeds the ShipperDog toolkit — nothing for you to do. Install it and crash context flows back to the team automatically.</p></li><li><p><strong>Report what you find.</strong> <strong>Report issue</strong> on any version opens the feedback form: pick a type (bug, feedback, crash, feature request, UX issue, or — if you found something that should not be public — security issue), describe it, attach screenshots or logs if you have them. The app, version, build, device, and OS are attached for you. Your reports go to the team&#39;s testers&#39; queue; the critical ones can hold a rollout outright, so early reports matter.</p></li></ol><p>That is the whole loop: install, test, report, repeat as new builds appear on your home screen.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>The step-by-step guides for each part of the portal:</p><ul><li><a href="/shipperdog/snapshot/how-to/portal/accept-invite">Accept an invitation</a></li><li><a href="/shipperdog/snapshot/how-to/portal/browse-apps">Browse your applications</a></li><li><a href="/shipperdog/snapshot/how-to/portal/install-ios">Install on iOS</a></li><li><a href="/shipperdog/snapshot/how-to/portal/install-android">Install on Android</a></li><li><a href="/shipperdog/snapshot/how-to/portal/feedback">Submit feedback</a></li></ul><p>The full walkthrough with the mechanics behind it: <a href="/shipperdog/snapshot/get-started/five-minute-install">five-minute install</a>.</p>',15)])])}const b=o(l,[["render",h]]);export{m as __pageData,b as default};
